        best_gain = 0
        best_merged = None
        for i in range(len(routes) - 1):
            a = routes[i]
            b = routes[i + 1]
            la = 0
            lb = 0
            for x in a:
                la += demand_of(x)
            for x in b:
                lb += demand_of(x)
            if la + lb > capacity:
                continue
            # Gain by concatenating routes in current order
            old_cost = dist(depot_id, a[0]) + dist(a[-1], depot_id) + dist(depot_id, b[0]) + dist(b[-1], depot_id)
            new_cost = dist(depot_id, a[0]) + dist(a[-1], b[0]) + dist(b[-1], depot_id)
            gain = old_cost - new_cost
            if gain > best_gain + 1e-12:
                best_gain = gain
                best_i = i
                best_merged = a + b
        if best_i >= 0:
            routes = routes[:best_i] + [best_merged] + routes[best_i + 2:]
            changed = True

    # --- Local search: intra-route 2-opt ---
    def route_load(route):
        s = 0
        for cid in route:
            s += demand_of(cid)
        return s

    def route_cost(route):
        if not route:
            return 0
        c = dist(depot_id, route[0]) + dist(route[-1], depot_id)
        for i in range(len(route) - 1):
            c += dist(route[i], route[i + 1])
        return c

    improved = True
    while improved:
        improved = False
        # 2-opt within each route
        for r_idx in range(len(routes)):
            r = routes[r_idx]
            n = len(r)
            if n < 4:
                continue
            best_delta = 0
            best_i = -1
            best_j = -1
            base = route_cost(r)
            for i in range(n - 2):
                for j in range(i + 2, n):
                    if i == 0 and j == n - 1:
                        continue
                    nr = r[:i + 1] + r[i + 1:j + 1][::-1] + r[j + 1:]
                    delta = base - route_cost(nr)
                    if delta > best_delta + 1e-12:
                        best_delta = delta
                        best_i = i
                        best_j = j
            if best_i >= 0:
                routes[r_idx] = r[:best_i + 1] + r[best_i + 1:best_j + 1][::-1] + r[best_j + 1:]
                improved = True

        # Inter-route relocate if it shortens and respects capacity
        best_move = None
        best_gain = 0
        for i in range(len(routes)):
            ri = routes[i]
            if not ri:
                continue
            li = route_load(ri)
            for p in range(len(ri)):
                cid = ri[p]
                d = demand_of(cid)
                for j in range(len(routes)):
                    if i == j:
                        continue
                    rj = routes[j]
                    lj = route_load(rj)
                    if lj + d > capacity:
                        continue
                    # try insertion positions
                    for q in range(len(rj) + 1):
                        nri = ri[:p] + ri[p + 1:]
                        nrj = rj[:q] + [cid] + rj[q:]
                        old = route_cost(ri) + route_cost(rj)
                        new = route_cost(nri) + route_cost(nrj)
                        gain = old - new
                        if gain > best_gain + 1e-12:
                            best_gain = gain
                            best_move = (i, j, p, q, nri, nrj)
        if best_move is not None:
            i, j, p, q, nri, nrj = best_move
            routes[i] = nri
            routes[j] = nrj
            routes = [r for r in routes if r]
            improved = True

    # Final cleanup: ensure every customer appears exactly once
    present = {}
    for r in routes:
        for cid in r:
            present[cid] = present.get(cid, 0) + 1

    missing = []
    dupes = []
    for cid in customer_ids:
        cnt = present.get(cid, 0)
        if cnt == 0:
            missing.append(cid)
        elif cnt > 1:
            dupes.append(cid)

    if missing or dupes:
        # Repair deterministically: remove duplicates beyond first and append missing greedily
        flat = []
        seen2 = {}
        for r in routes:
            nr = []
            for cid in r:
                if seen2.get(cid, 0) == 0:
                    nr.append(cid)
                    seen2[cid] = 1
                else:
                    pass
            if nr:
                flat.append(nr)
        routes = flat
        for cid in missing:
            placed = False
            d = demand_of(cid)
            best_r = -1
            best_pos = -1
            best_increase = None
            for i, r in enumerate(routes):
                if route_load(r) + d > capacity:
                    continue
                for pos in range(len(r) + 1):
                    old = route_cost(r)
                    nr = r[:pos] + [cid] + r[pos:]
                    inc = route_cost(nr) - old
                    if best_increase is None or inc < best_increase - 1e-12 or (abs(inc - best_increase) <= 1e-12 and (i, pos) < (best_r, best_pos)):
                        best_increase = inc
                        best_r = i
                        best_pos = pos
                        placed = True
            if placed:
                r = routes[best_r]
                routes[best_r] = r[:best_pos] + [cid] + r[best_pos:]
            else:
                routes.append([cid])

    # Remove empty routes, keep determinism
    routes = [r for r in routes if r]
    return routes
